import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#include <cute/tensor.hpp>
using namespace cute;
constexpr int ROWS_PER_BLOCK = 32; // larger CTA output tile reduces redundant re-reads of B across row-blocks
constexpr int TILE_K = 1024; // must be divisible by 4
constexpr int SPLIT_K = 4;   // split large K dimension across blocks for better parallelism
constexpr int THREADS = 256;
constexpr int WARP_SIZE = 32;
constexpr int NWARPS = THREADS / WARP_SIZE;
constexpr int ROWS_PER_WARP = ROWS_PER_BLOCK / NWARPS; // warp-level tiling: each warp owns a disjoint subset of rows
__device__ __forceinline__ int swz_idx(int i) {
    // Diagonal swizzle applied to the shared-memory index used for the
    // B tile: redistributes the physical bank mapping of consecutive
    // float4 elements accessed by a warp (lanes i and i+8 previously
    // aliased to the same bank group), while remaining a bijection over
    // [0, tileK4) so writes (cp.async) and reads still refer to the
    // same logical B value for a given i.
    int row = i >> 3;
    int col = i & 7;
    return (row << 3) | ((col + row) & 7);
}
__global__ void cute_matvec_kernel(
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C,
    int M, int K, int split_k)
{
    int block_row = blockIdx.x * ROWS_PER_BLOCK;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int lane = tid & (WARP_SIZE - 1);
    int warp_id = tid >> 5;
    // Determine this block's slice of the K dimension (split-K).
    int chunk = (K / split_k) & ~3; // multiple of 4 for float4 alignment
    if (chunk <= 0) chunk = 4;
    int k_start = blockIdx.y * chunk;
    if (k_start >= K) return;
    int k_end = (blockIdx.y == split_k - 1) ? K : min(K, k_start + chunk);
    int local_K = k_end - k_start;
    if (local_K <= 0) return;
    // Shared-memory tile of B, reused across ROWS_PER_BLOCK rows of A
    // to cut down redundant global memory reads of B (which is the
    // same vector reloaded for every output row).
    __shared__ float4 smB[2][TILE_K / 4];
    // Warp-level tiling: each warp is responsible for a fixed, disjoint
    // subset of ROWS_PER_WARP rows instead of every thread carrying an
    // accumulator for all ROWS_PER_BLOCK rows. This shrinks the live
    // per-thread register footprint from ROWS_PER_BLOCK accumulators
    // (and pointers) down to ROWS_PER_WARP, improving occupancy while
    // doing exactly the same total amount of work, and it also removes
    // the need for a second cross-warp reduction stage since each row
    // is now owned by a single warp.
    int warp_row_base = block_row + warp_id * ROWS_PER_WARP;
    float sums[ROWS_PER_WARP];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_WARP; r++) sums[r] = 0.f;
    int K4 = local_K / 4;
    int tileK4 = TILE_K / 4;
    const float4* B4 = reinterpret_cast<const float4*>(B + k_start);
    // Precompute per-row A pointers once (loop-invariant across all tiles)
    // instead of recomputing the row base address (m * K) on every tile
    // iteration, which cuts redundant integer multiplication/address math.
    const float4* A4_row[ROWS_PER_WARP];
    #pragma unroll
    for (int r = 0; r < ROWS_PER_WARP; r++) {
        int m = warp_row_base + r;
        A4_row[r] = (m < M) ? reinterpret_cast<const float4*>(A + (size_t)m * (size_t)K + k_start) : nullptr;
    }
    int num_tiles = K4 / tileK4;
    if (num_tiles > 0) {
        // Prime the pipeline: asynchronously load the first tile into buffer 0
        // using cp.async so the copy overlaps with subsequent setup work.
        for (int i = tid; i < tileK4; i += nthreads) {
            __pipeline_memcpy_async(&smB[0][swz_idx(i)], &B4[i], sizeof(float4));
        }
        __pipeline_commit();
        __pipeline_wait_prior(0);
        __syncthreads();
        int cur = 0;
        for (int tile = 0; tile < num_tiles; tile++) {
            int next = cur ^ 1;
            // Prefetch the next tile into the other buffer asynchronously (cp.async)
            // while computing on the current tile, truly overlapping global memory
            if (tile + 1 < num_tiles) {
                int base4_next = (tile + 1) * tileK4;
                for (int i = tid; i < tileK4; i += nthreads) {
                    __pipeline_memcpy_async(&smB[next][swz_idx(i)], &B4[base4_next + i], sizeof(float4));
                }
                __pipeline_commit();
            }
            int base4 = tile * tileK4;
            #pragma unroll
            for (int r = 0; r < ROWS_PER_WARP; r++) {
                const float4* A4 = A4_row[r];
                if (A4 != nullptr) {
                    float local = 0.f;
                    for (int i = lane; i < tileK4; i += WARP_SIZE) {
                        float4 a = A4[base4 + i];
                        float4 b = smB[cur][swz_idx(i)];
                        local += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
                    }
                    sums[r] += local;
                }
            }
            if (tile + 1 < num_tiles) {
                __pipeline_wait_prior(0);
            }
            __syncthreads();
            cur = next;
        }
    }
    int rem4 = K4 - num_tiles * tileK4;
    if (rem4 > 0) {
        int base4 = num_tiles * tileK4;
        for (int i = tid; i < rem4; i += nthreads) {
            smB[0][i] = B4[base4 + i];
        }
        __syncthreads();
        #pragma unroll
        for (int r = 0; r < ROWS_PER_WARP; r++) {
            const float4* A4 = A4_row[r];
            if (A4 != nullptr) {
                float local = 0.f;
                for (int i = lane; i < rem4; i += WARP_SIZE) {
                    float4 a = A4[base4 + i];
                    float4 b = smB[0][i];
                    local += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
                }
                sums[r] += local;
            }
        }
        __syncthreads();
    }
    // Scalar remainder for local_K not divisible by 4
    int rem_start = K4 * 4;
    #pragma unroll
    for (int r = 0; r < ROWS_PER_WARP; r++) {
        int m = warp_row_base + r;
        if (m < M) {
            float local = 0.f;
            for (int i = rem_start + lane; i < local_K; i += WARP_SIZE) {
                local += A[(size_t)m * (size_t)K + k_start + i] * B[k_start + i];
            }
            sums[r] += local;
        }
    }
    // Warp-level reduction only: each warp owns disjoint rows, so no
    // cross-warp reduction step or extra shared memory buffer is needed.
    #pragma unroll
    for (int r = 0; r < ROWS_PER_WARP; r++) {
        float sum = sums[r];
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            sum += __shfl_down_sync(0xffffffff, sum, offset);
        }
        int m = warp_row_base + r;
        if (lane == 0 && m < M) {
            atomicAdd(&C[m], sum);
        }
    }
}
torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2, "A must be 2D");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be (K, 1)");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    int M = (int)A.size(0);
    int K = (int)A.size(1);
    TORCH_CHECK((int)B.size(0) == K, "B.size(0) must equal A.size(1)");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    // C must start at zero because split-K partial sums are accumulated via atomicAdd.
    auto C = torch::zeros({M, 1}, A.options());
    int threads = 256;
    int split_k = SPLIT_K;
    dim3 block(threads);
    dim3 grid((M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK, split_k);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_matvec_kernel<<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(), M, K, split_k);
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE matvec launch failed");
    return C;
}
"""

cute_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix-vector multiplication (C = A * B)
    using a custom CuTe/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec(A, B)


M = 256 * 8  # 2048
K = 131072 * 8  # 1048576


def get_inputs():
    A = torch.rand(M, K).cuda()
    B = torch.rand(K, 1).cuda()
    return [A, B]


def get_init_inputs():
    return []

